async function risky() { throw new Error('db fail'); }
const stack = [];
function use(fn) { stack.push(fn); }
function run(ctx, final) {
  let i = 0;
  function next(err) {
    while (i < stack.length) {
      const mw = stack[i];
      if (err) { if (mw.length === 4) { i++; mw(err, ctx, {}, next); return; } i++; continue; }
      if (mw.length === 4) { i++; continue; }
      i++;
      try { const r = mw(ctx, next); if (r && r.catch) r.catch(e => next(e)); } catch (e) { next(e); }
      return;
    }
    if (err) { ctx.log.push('UNHANDLED:' + err.message); return; }
    final(ctx);
  }
  next();
}
// 修复：用 try/catch 把 async 错误传给 next(err)
use(async (c, n) => { try { await risky(); } catch (e) { return n(e); } await n(); });
use((err, c, req, n) => { c.log.push('status=500'); });
const ctx = { log: [] };
run(ctx, c => c.log.push('ok'));
console.log(ctx.log.join('|'));

function compose(middlewares) {
  return function (ctx, final) {
    let i = 0;
    function next(err) {
      while (i < middlewares.length) {
        const mw = middlewares[i];
        if (err) {
          if (mw.length === 4) { i++; mw(err, ctx, {}, next); return; }
          i++; continue;
        }
        if (mw.length === 4) { i++; continue; }
        i++;
        try {
          const r = mw(ctx, next);
          if (r && typeof r.then === 'function') r.catch(e => next(e));
        } catch (e) { next(e); }
        return;
      }
      if (err) { ctx.log.push('UNHANDLED:' + err.message); return; }
      final(ctx);
    }
    next();
  };
}
const stack = [];
const use = fn => stack.push(fn);
const run = compose(stack);
use((c, n) => { c.log.push('A'); n(); c.log.push('A-out'); });
use((c, n) => { c.log.push('B'); n(); });
const ctx = { log: [] };
run(ctx, c => c.log.push('final'));
console.log(ctx.log.join('>'));

function matchRoute(method, path, routes) {
  for (const r of routes) {
    if (r.method !== method) continue;
    const keys = [];
    const rx = new RegExp('^' + r.pattern.replace(/:(\w+)/g, (_, k) => { keys.push(k); return '([^/]+)'; }) + '$');
    const m = rx.exec(path);
    if (m) { const params = {}; keys.forEach((k, i) => params[k] = m[i + 1]); return { handler: r.handler, params }; }
  }
  return null;
}
const routes = [
  { method: 'GET', pattern: '/items', handler: () => 'list' },
  { method: 'GET', pattern: '/items/:id', handler: () => 'one' },
];
console.log(JSON.stringify(matchRoute('GET', '/items/42', routes).params));
console.log(matchRoute('POST', '/items', routes) === null);

function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
  return [];
}
